function dashboardDateMatch(item,key='emissao'){if(dashboardPeriod==='all')return true;const value=item[key]||item.emissao||item.atualizadoEm||item.validade;if(!value)return false;const date=new Date(`${value}T12:00:00`);if(Number.isNaN(date.getTime()))return false;if(dashboardPeriod==='30d'){const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-29);return date>=cutoff}if(dashboardPeriod==='month')return String(value).slice(0,7)===dashboardMonth;const from=dashboardFrom?new Date(`${dashboardFrom}T00:00:00`):null;const to=dashboardTo?new Date(`${dashboardTo}T23:59:59`):null;return (!from||date>=from)&&(!to||date<=to)}
