function loadQrDecoder(){if(window.jsQR)return Promise.resolve(window.jsQR);return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js';script.onload=()=>window.jsQR?resolve(window.jsQR):reject(new Error('QR decoder unavailable'));script.onerror=reject;document.head.appendChild(script)})}
function loadZxingDecoder(){if(window.ZXing)return Promise.resolve(window.ZXing);return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@zxing/library@0.21.3/umd/index.min.js';script.onload=()=>window.ZXing?resolve(window.ZXing):reject(new Error('Barcode decoder unavailable'));script.onerror=reject;document.head.appendChild(script)})}
if(!('BarcodeDetector' in window)){window.BarcodeDetector=class{constructor(){this.canvas=document.createElement('canvas');this.context=this.canvas.getContext('2d',{willReadFrequently:true});this.decoder=null}async detect(video){const zxing=await loadZxingDecoder();this.canvas.width=video.videoWidth;this.canvas.height=video.videoHeight;if(!this.canvas.width||!this.canvas.height)return[];this.context.drawImage(video,0,0,this.canvas.width,this.canvas.height);const rgba=this.context.getImageData(0,0,this.canvas.width,this.canvas.height).data;const luminance=new Uint8ClampedArray(this.canvas.width*this.canvas.height);for(let i=0,j=0;i<rgba.length;i+=4,j++)luminance[j]=(rgba[i]*299+rgba[i+1]*587+rgba[i+2]*114)/1000;const source=new zxing.RGBLuminanceSource(luminance,this.canvas.width,this.canvas.height);const bitmap=new zxing.BinaryBitmap(new zxing.HybridBinarizer(source));if(!this.decoder){this.decoder=new zxing.MultiFormatReader;const hints=new Map;hints.set(zxing.DecodeHintType.POSSIBLE_FORMATS,[zxing.BarcodeFormat.QR_CODE,zxing.BarcodeFormat.EAN_13,zxing.BarcodeFormat.EAN_8,zxing.BarcodeFormat.UPC_A,zxing.BarcodeFormat.UPC_E,zxing.BarcodeFormat.CODE_128,zxing.BarcodeFormat.CODE_39,zxing.BarcodeFormat.ITF]);hints.set(zxing.DecodeHintType.TRY_HARDER,true);this.decoder.setHints(hints)}try{const result=this.decoder.decode(bitmap);this.decoder.reset();return result?[{rawValue:result.getText()}]:[]}catch{this.decoder.reset();return[]}}}}
async function startPdvScanner(){if(!navigator.mediaDevices?.getUserMedia){showToast('A câmera não está disponível neste dispositivo. Use HTTPS e permita o acesso à câmera.');return}closePdvScanner();const overlay=document.createElement('div');overlay.id='pdvScanner';overlay.className='pdv-scanner-backdrop';overlay.innerHTML='<div class="pdv-scanner-modal" role="dialog" aria-modal="true" aria-labelledby="pdvScannerTitle"><div class="pdv-scanner-head"><strong id="pdvScannerTitle">Ler código de barras ou QR Code</strong><button type="button" class="modal-close pdv-scanner-close" data-pdv-scan-close aria-label="Fechar leitor">×</button></div><div class="pdv-scanner-view"><video autoplay playsinline muted></video><div class="pdv-scanner-guide"></div></div><small class="pdv-scanner-feedback" role="status">Aponte a câmera para o código. Você pode escanear vários itens seguidos.</small><button type="button" class="btn primary pdv-scanner-finish" disabled>Finalizar compra</button></div>';document.body.appendChild(overlay);const finishButton=overlay.querySelector('.pdv-scanner-finish');overlay.querySelector('[data-pdv-scan-close]').onclick=closePdvScanner;finishButton.onclick=()=>{closePdvScanner();document.querySelector('[data-pdv-finish]')?.click()};try{pdvScannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});const video=overlay.querySelector('video');const feedback=overlay.querySelector('.pdv-scanner-feedback');video.srcObject=pdvScannerStream;await video.play();const detector=new BarcodeDetector({formats:['qr_code','ean_13','ean_8','upc_a','upc_e','code_128','code_39','itf']});let lockedCode='';let codeMissingSince=0;let scannedCount=0;const detect=async()=>{if(!document.body.contains(overlay))return;try{const codes=await detector.detect(video);const code=String(codes[0]?.rawValue||'').trim();if(!code){if(lockedCode){if(!codeMissingSince)codeMissingSince=performance.now();else if(performance.now()-codeMissingSince>=600){lockedCode='';codeMissingSince=0;feedback.textContent='Pronto para o próximo item.'}}}else{codeMissingSince=0;if(code!==lockedCode){lockedCode=code;const normalizedCode=code.toLowerCase();const product=db.produtos.find(x=>String(x.sku||'').toLowerCase()===normalizedCode||String(x.codigo||'').toLowerCase()===normalizedCode);if(product&&Number(product.estoque)>0){addPdvProduct(product);pdvQuery='';scannedCount++;finishButton.disabled=false;finishButton.textContent=`Finalizar compra (${scannedCount})`;feedback.textContent=`${product.nome} adicionado. Afaste o código para ler novamente.`;showToast(`${product.nome} adicionado ao carrinho.`)}else{pdvQuery=code;feedback.textContent=`Código ${code} não localizado. Aponte para o próximo item.`;showToast(`Código ${code} lido. Nenhum produto correspondente foi localizado.`)}render('pdv')}}}catch{}pdvScannerFrame=requestAnimationFrame(detect)};pdvScannerFrame=requestAnimationFrame(detect)}catch{closePdvScanner();showToast('Não foi possível acessar a câmera. Verifique a permissão do navegador e tente novamente.')}}
document.addEventListener('click',e=>{const add=e.target.closest('[data-pdv-add]');if(add){const p=db.produtos.find(x=>x.id===Number(add.dataset.pdvAdd));if(!p)return;addPdvProduct(p);render('pdv');return}const qty=e.target.closest('[data-pdv-qty]');if(qty){const [id,delta]=qty.dataset.pdvQty.split(':').map(Number);const item=pdvCart.find(x=>x.id===id);if(item){item.qty+=delta;if(item.qty<=0)pdvCart=pdvCart.filter(x=>x.id!==id);render('pdv')}return}if(e.target.closest('[data-pdv-clear]')){pdvCart=[];render('pdv');return}if(e.target.closest('[data-pdv-finish]')&&pdvCart.length){const total=pdvCart.reduce((s,item)=>s+item.qty*Number(item.valorVenda),0);checkpoint();pdvCart.forEach(item=>{const product=db.produtos.find(x=>x.id===item.id);if(product)product.estoque=Math.max(0,Number(product.estoque)-item.qty)});db.pedidos.unshift({id:Math.max(1000,...db.pedidos.map(x=>x.id))+1,comprador:'Venda presencial',emissao:new Date().toISOString().slice(0,10),valor:total,status:'Faturado',editadoPor:'Lucas Almeida',editadoEm:new Date().toISOString().slice(0,10)});saveData();pdvCart=[];showToast(`Venda presencial registrada: ${money(total)}.`);render('dashboard')}});
