function duplicateRecord(type,id){const source=db[type]?.find(x=>x.id===Number(id));if(!source)return;checkpoint();const nextId=Math.max(0,...db[type].map(x=>Number(x.id)||0))+1;const copy={...source,id:nextId};if(copy.nome)copy.nome=`${copy.nome} (cópia)`;if(copy.comprador&&type!=='pedidos'&&type!=='orcamentos')copy.comprador=`${copy.comprador} (cópia)`;if(type==='pedidos'){copy.editadoPor='Lucas Almeida';copy.editadoEm=new Date().toISOString().slice(0,10)}db[type].unshift(copy);saveData();showToast('Registro duplicado.');render(currentPage)}
