var originalClientTableWithStatusMenu=table;table=function(type,rows){if(type!=='compradores')return originalClientTableWithStatusMenu(type,rows);const config=configs[type];if(!rows.length)return '<div class="filter-empty">Nenhum registro encontrado para os filtros informados.</div>';const statusMenu=clientStatusMenuOpen?`<div class="table-filter-popover"><button type="button" data-client-status="Todos os status">Todos os status</button><button type="button" data-client-status="Ativo">Ativo</button><button type="button" data-client-status="Alerta">Alerta</button><button type="button" data-client-status="Inativo">Inativo</button></div>`:'';return `<table class="data-table"><thead><tr>${config.columns.map(c=>{if(c[0]==='ultimaCompra')return `<th><button type="button" class="table-header-filter" data-client-sort>Última compra <span>${clientSort==='recent'?'↓':'↑'}</span></button></th>`;if(c[0]==='status')return `<th class="table-filter-header"><button type="button" class="table-header-filter" data-client-status-filter>Status <span>⌄</span></button>${statusMenu}</th>`;return `<th>${c[1]}</th>`}).join('')}<th>Ações</th></tr></thead><tbody>${rows.map(row=>`<tr class="editable-row" data-row-edit="${type}:${row.id}" tabindex="0" title="Clique na linha para editar">${config.columns.map(c=>`<td>${formatCell(type,row,c)}</td>`).join('')}<td><div class="row-actions"><button class="action-button danger" title="Excluir" data-delete="${type}:${row.id}">⌫</button></div></td></tr>`).join('')}</tbody></table>`};
document.addEventListener('click',e=>{const header=e.target.closest('[data-client-status-filter]');const choice=e.target.closest('[data-client-status]');if(header||choice){e.preventDefault();e.stopImmediatePropagation();if(choice){filterState.status=choice.dataset.clientStatus;clientStatusMenuOpen=false;refreshTableKeepingFocus()}else{clientStatusMenuOpen=!clientStatusMenuOpen;refreshTableKeepingFocus()}}},true);
