mountMessagePreviews=function(){document.querySelectorAll('textarea[name="mensagemEmail"],textarea[name="mensagemWhatsApp"]').forEach(area=>{let preview=area.nextElementSibling?.matches('.message-preview')?area.nextElementSibling:null;if(!preview){preview=document.createElement('div');preview.className='message-preview';area.insertAdjacentElement('afterend',preview)}const channel=area.name==='mensagemEmail'?'E-mail':'WhatsApp';const html=`<strong>Prévia da mensagem (${channel})</strong><p>${escapeHtml(area.value.replace(/<nome>/gi,'Lucas Almeida'))}</p>`;if(preview.innerHTML!==html)preview.innerHTML=html})};
function clientStatus(client){if(client.status==='Inativo')return 'Inativo';if(client.ultimaCompra){const days=daysSince(client.ultimaCompra);const start=Number(db.configuracoes.diasClienteSemCompra);const end=Number(db.configuracoes.diasClienteAlertaAte??start);if(days>=end)return 'Inativo';if(days>=start)return 'Alerta'}return 'Ativo'}
