var originalFormatCellForClients=formatCell;formatCell=function(type,row,column){if(type==='compradores'&&column[0]==='status'){const status=clientStatus(row);return `<span class="badge ${status==='Alerta'?'amber':badgeClass(status)}">${status}</span>`}return originalFormatCellForClients(type,row,column)};
function settingsPage(){const c=db.configuracoes;return `<div class="page-head"><div><div class="eyebrow">Preferências</div><h1>Configurações de alertas</h1><p>Defina alertas, markup padrão e personalize as mensagens de contato.</p></div></div><div class="settings-grid single"><form class="card settings-card" id="notificationSettings"><div class="panel-head"><div><h2>Limites das notificações</h2><small>As mudanças recalculam os alertas imediatamente.</small></div></div><label>Cliente entra em alerta a partir de<input name="diasClienteSemCompra" type="number" min="1" value="${c.diasClienteSemCompra}" required><span class="field-suffix">dias</span><small>Início da faixa em que o cliente será exibido como “Alerta”.</small></label><label>Cliente sai do alerta após<input name="diasClienteAlertaAte" type="number" min="1" value="${c.diasClienteAlertaAte??120}" required><span class="field-suffix">dias</span><small>Fim da faixa de alerta. Depois desse limite, o status volta para “Ativo”, salvo se estiver inativo manualmente.</small></label><label>Orçamento sem retorno há<input name="diasOrcamentoSemRetorno" type="number" min="1" value="${c.diasOrcamentoSemRetorno}" required><span class="field-suffix">dias</span><small>Considera propostas enviadas ou em análise sem movimentação.</small></label><label>Antecedência de faturas de fornecedores<input name="diasAntecedenciaFatura" type="number" min="1" value="${c.diasAntecedenciaFatura}" required><span class="field-suffix">dias</span><small>Somente faturas vinculadas a fornecedores cadastrados.</small></label><label>Markup padrão para novos produtos<input name="markupPadrao" type="number" min="0" step="0.01" value="${c.markupPadrao??''}"><small>Opcional. Será preenchido automaticamente no cadastro de novos produtos.</small></label><div class="settings-divider"></div><div class="panel-head message-heading"><div><h2>Mensagens padrão</h2><small>Use <code>&lt;nome&gt;</code> onde deseja inserir automaticamente o nome do cliente.</small></div></div><label>Mensagem para e-mail<textarea name="mensagemEmail" rows="6" required>${escapeHtml(c.mensagemEmail)}</textarea></label><label>Mensagem para WhatsApp<textarea name="mensagemWhatsApp" rows="4" required>${escapeHtml(c.mensagemWhatsApp)}</textarea></label><div class="template-example"><strong>Exemplo</strong><span>“Bom dia, <code>&lt;nome&gt;</code>, gostaria de apresentar o produto a seguir...”</span></div><button class="btn primary" type="submit">Salvar configurações</button></form></div><div class="permission-note"><span>🔒</span><p><strong>Notificações de edição por outros funcionários</strong><br>Somente administradores e gestores com permissão de auditoria podem visualizar quem editou um pedido.</p></div>`}
saveNotificationSettings=function(event){event.preventDefault();const data=new FormData(event.currentTarget);const markupValue=String(data.get('markupPadrao')||'').replace('%','').replace(',','.').trim();checkpoint();db.configuracoes={...db.configuracoes,diasClienteSemCompra:Number(data.get('diasClienteSemCompra')),diasClienteAlertaAte:Number(data.get('diasClienteAlertaAte')),diasOrcamentoSemRetorno:Number(data.get('diasOrcamentoSemRetorno')),diasAntecedenciaFatura:Number(data.get('diasAntecedenciaFatura')),markupPadrao:markupValue===''?null:Number(markupValue),mensagemEmail:String(data.get('mensagemEmail')).trim(),mensagemWhatsApp:String(data.get('mensagemWhatsApp')).trim()};saveData();showToast('Configurações e mensagens salvas.');render('configuracoes')};
function settingsPage(){const c=db.configuracoes;return `<div class="page-head"><div><div class="eyebrow">Preferências</div><h1>Configurações</h1><p>Organize as regras e mensagens por módulo do sistema.</p></div></div><div class="settings-grid single"><form class="card settings-card" id="notificationSettings"><section class="settings-module"><div class="settings-module-head"><span>♙</span><div><h2>Clientes</h2><small>Defina quando um cliente deve chamar atenção.</small></div></div><div class="form-row"><label>Alerta a partir de<input name="diasClienteSemCompra" type="number" min="1" value="${c.diasClienteSemCompra}" required><span class="field-suffix">dias</span></label><label>Inativo a partir de<input name="diasClienteAlertaAte" type="number" min="1" value="${c.diasClienteAlertaAte??120}" required><span class="field-suffix">dias</span></label></div><small class="module-help">Menos de X dias: Ativo · de X até antes de Y: Alerta · a partir de Y: Inativo.</small></section><section class="settings-module"><div class="settings-module-head"><span>▤</span><div><h2>Orçamentos</h2><small>Controle propostas sem retorno.</small></div></div><label>Orçamento sem retorno há<input name="diasOrcamentoSemRetorno" type="number" min="1" value="${c.diasOrcamentoSemRetorno}" required><span class="field-suffix">dias</span></label></section><section class="settings-module"><div class="settings-module-head"><span>$</span><div><h2>Fornecedores</h2><small>Antecedência para alertas de faturas.</small></div></div><label>Antecedência de faturas de fornecedores<input name="diasAntecedenciaFatura" type="number" min="1" value="${c.diasAntecedenciaFatura}" required><span class="field-suffix">dias</span></label></section><section class="settings-module"><div class="settings-module-head"><span>◇</span><div><h2>Produtos</h2><small>Valor padrão para novos cadastros.</small></div></div><label>Markup padrão para novos produtos<input name="markupPadrao" type="number" min="0" step="0.01" value="${c.markupPadrao??''}"><small>Opcional. Pode ser alterado individualmente no cadastro do produto.</small></label></section><section class="settings-module"><div class="settings-module-head"><span>✉</span><div><h2>Minha conta / Comunicação</h2><small>Mensagens usadas ao contatar clientes.</small></div></div><label>Mensagem para e-mail<textarea name="mensagemEmail" rows="5" required>${escapeHtml(c.mensagemEmail)}</textarea><small>Use <code>&lt;nome&gt;</code> para inserir automaticamente o nome do cliente.</small><label>Mensagem para WhatsApp<textarea name="mensagemWhatsApp" rows="4" required>${escapeHtml(c.mensagemWhatsApp)}</textarea><small>Use <code>&lt;nome&gt;</code> para inserir automaticamente o nome do cliente.</small></label></section><button class="btn primary" type="submit">Salvar configurações</button></form></div><div class="permission-note"><span>🔒</span><p><strong>Notificações de edição por outros funcionários</strong><br>Somente administradores e gestores com permissão de auditoria podem visualizar quem editou um pedido.</p></div>`}
function filtered(type,subset){let rows=[...(subset?db[type].filter(subset):db[type])];const rawQuery=filterState.query.toLocaleLowerCase('pt-BR').trim();if(rawQuery){if(type==='compradores'){const query=rawQuery.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');rows=rows.filter(x=>['nome','documento','email','telefone'].some(key=>String(x[key]??'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'').includes(query)))}else rows=rows.filter(x=>Object.values(x).some(v=>String(v).toLocaleLowerCase('pt-BR').includes(rawQuery)))}if(filterState.status!=='Todos os status')rows=rows.filter(x=>type==='pedidos'?orderStatusLabel(x.status)===filterState.status:x.status===filterState.status);if(type==='pedidos'&&filterState.dateFrom)rows=rows.filter(x=>x.emissao>=filterState.dateFrom);if(type==='pedidos'&&filterState.dateTo)rows=rows.filter(x=>x.emissao<=filterState.dateTo);if(filterState.order==='Nome A–Z')rows.sort((a,b)=>String(a.nome||a.comprador).localeCompare(String(b.nome||b.comprador),'pt-BR'));else rows.sort((a,b)=>Number(b.id)-Number(a.id));return rows}
function ticketMonthOptions(){const now=new Date();return Array.from({length:12},(_,i)=>{const date=new Date(now.getFullYear(),now.getMonth()-i,1);const value=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;const label=date.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});return `<button type="button" class="ticket-month-option ${ticketMonth===value?'active':''}" data-ticket-month-option="${value}">${label}</button>`}).join('')}
function ticketKpi(){const orders=ticketOrders();const average=orders.length?orders.reduce((s,x)=>s+Number(x.valor),0)/orders.length:0;return `<section class="card kpi ticket-kpi" data-tooltip="Valor médio por pedido no período selecionado no dashboard."><div class="kpi-top"><span>Ticket médio</span><span class="kpi-icon">◇</span></div><strong>${money(average)}</strong><span class="trend">${orders.length} pedidos no período</span></section>`}
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-ticket-month-trigger]');if(trigger){ticketPeriod='month';ticketMonthPickerOpen=!ticketMonthPickerOpen;render('dashboard',{preserveScroll:true});return}const option=e.target.closest('[data-ticket-month-option]');if(option){ticketMonth=option.dataset.ticketMonthOption;ticketPeriod='month';ticketMonthPickerOpen=false;render('dashboard',{preserveScroll:true});return}if(!e.target.closest('.ticket-controls')&&ticketMonthPickerOpen){ticketMonthPickerOpen=false;render('dashboard',{preserveScroll:true})}});
function payExternalAccount(id){const item=db.contasExternas.find(x=>x.id===Number(id));if(!item)return;checkpoint();item.paga=true;saveData();showToast('Conta marcada como paga.');render('contas')}
function payInternalInvoice(id){const item=db.faturas.find(x=>x.id===Number(id));if(!item)return;checkpoint();item.paga=true;saveData();showToast('Conta interna marcada como paga.');render('contas')}
function contasPagarPage(){const internal=db.faturas,external=db.contasExternas||[],all=[...internal.map(x=>({...x,origem:'Interna'})),...external.map(x=>({...x,origem:'Externa'}))],open=all.filter(x=>!x.paga),total=open.reduce((s,x)=>s+Number(x.valor),0);const row=x=>`<tr class="editable-row" data-row-edit="${x.origem==='Externa'?'contasExternas':'faturas'}:${x.id}" tabindex="0"><td><strong>${escapeHtml(x.descricao)}</strong></td><td>${escapeHtml(x.fornecedor||'—')}</td><td>${datePt(x.vencimento)}</td><td><strong>${money(x.valor)}</strong></td><td><span class="badge ${x.origem==='Interna'?'blue':''}">${x.origem}</span></td><td>${x.paga?'<span class="badge green">Paga</span>':`<button class="btn secondary pay-button" data-pay-${x.origem==='Interna'?'internal':'external'}="${x.id}">Marcar como paga</button>`}</td></tr>`;return `<div class="page-head"><div><div class="eyebrow">Financeiro</div><h1>Contas a pagar</h1><p>Controle contas geradas pelo sistema e lançamentos externos.</p></div><button class="btn primary" data-add="contasExternas">＋ Nova conta externa</button></div><div class="filtered-total-card"><div><small>Total em aberto</small><strong>${money(total)}</strong></div><span>${open.length} conta(s) pendente(s)</span></div><div class="payables-grid"><section class="card table-card"><div class="panel-head payables-section-head"><div><h2>Contas internas</h2><small>Geradas automaticamente por fornecedores e módulos do sistema.</small></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Descrição</th><th>Beneficiário</th><th>Vencimento</th><th>Valor</th><th>Origem</th><th>Status</th></tr></thead><tbody>${internal.map(x=>row({...x,origem:'Interna'})).join('')}</tbody></table></div></section><section class="card table-card"><div class="panel-head payables-section-head"><div><h2>Contas externas</h2><small>Incluídas manualmente pelo usuário.</small></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Descrição</th><th>Beneficiário</th><th>Vencimento</th><th>Valor</th><th>Origem</th><th>Status</th></tr></thead><tbody>${external.length?external.map(x=>row({...x,origem:'Externa'})).join(''):'<tr><td colspan="6"><div class="filter-empty">Nenhuma conta externa cadastrada.</div></td></tr>'}</tbody></table></div></section></div>`}
var originalRenderForPayables=render;render=function(page=currentPage,options={}){if(page!=='contas')return originalRenderForPayables(page,options);currentPage=page;document.getElementById('content').innerHTML=contasPagarPage();document.querySelectorAll('.nav-item,.nav-subitem').forEach(x=>x.classList.toggle('active',x.dataset.page===page));bindPage();updateNotifications();document.getElementById('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})};
document.addEventListener('click',e=>{const internal=e.target.closest('[data-pay-internal]');if(internal){e.preventDefault();e.stopPropagation();payInternalInvoice(internal.dataset.payInternal)}const external=e.target.closest('[data-pay-external]');if(external){e.preventDefault();e.stopPropagation();payExternalAccount(external.dataset.payExternal)}});
var originalSubmitForPayables=submitForm;submitForm=function(event){if(editContext?.type==='contasExternas'){const original=event.currentTarget;const paid=original.elements.paga?.value==='Paga';const targetId=editContext.id;originalSubmitForPayables(event);const target=db.contasExternas.find(x=>x.id===targetId)||db.contasExternas[0];if(target)target.paga=paid;saveData();return}originalSubmitForPayables(event)};
var originalFieldHtmlForPayables=fieldHtml;fieldHtml=function(f,value,index){if(f.key==='paga'&&editContext?.type==='contasExternas'){const selected=value===true?'Paga':'Pendente';return `${index%2===0?'<div class="form-row">':''}<label>${f.label}<select name="paga"><option ${selected==='Pendente'?'selected':''}>Pendente</option><option ${selected==='Paga'?'selected':''}>Paga</option></select></label>${index%2===1||index===configs.contasExternas.fields.length-1?'</div>':''}`}return originalFieldHtmlForPayables(f,value,index)};
function remessasPage(){const remessas=[...(db.remessas||[])].sort((a,b)=>b.data.localeCompare(a.data));const boletos=db.faturas.filter(x=>!x.paga);const total=boletos.reduce((sum,x)=>sum+Number(x.valor),0);return `<div class="page-head"><div><div class="eyebrow">Financeiro</div><h1>Remessas de boletos</h1><p>Organize boletos em arquivos de remessa para envio ao banco.</p></div><button class="btn primary" data-create-remessa ${boletos.length?'':'disabled'}>＋ Gerar nova remessa</button></div><div class="filtered-total-card"><div><small>Boletos pendentes</small><strong>${boletos.length}</strong></div><span>Valor total ${money(total)}</span></div><section class="card table-card"><div class="panel-head"><div><h2>Boletos disponíveis</h2><small>Faturas não pagas que podem ser incluídas na próxima remessa.</small></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Descrição</th><th>Fornecedor</th><th>Vencimento</th><th>Valor</th><th>Status</th></tr></thead><tbody>${boletos.length?boletos.map(x=>`<tr><td><strong>${escapeHtml(x.descricao)}</strong></td><td>${escapeHtml(x.fornecedor)}</td><td>${datePt(x.vencimento)}</td><td><strong>${money(x.valor)}</strong></td><td><span class="badge amber">Pendente</span></td></tr>`).join(''):'<tr><td colspan="5"><div class="filter-empty">Nenhum boleto pendente.</div></td></tr>'}</tbody></table></div></section><section class="card table-card" style="margin-top:16px"><div class="panel-head"><div><h2>Histórico de remessas</h2><small>Arquivos gerados neste protótipo.</small></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Remessa</th><th>Data</th><th>Banco</th><th>Boletos</th><th>Valor</th><th>Status</th></tr></thead><tbody>${remessas.map(x=>`<tr><td><strong>#${x.id}</strong></td><td>${datePt(x.data)}</td><td>${escapeHtml(x.banco)}</td><td>${x.boletos}</td><td><strong>${money(x.valor)}</strong></td><td><span class="badge green">${escapeHtml(x.status)}</span></td></tr>`).join('')}</tbody></table></div></section>`}
function createRemessa(){const boletos=db.faturas.filter(x=>!x.paga);if(!boletos.length)return;checkpoint();if(!db.remessas)db.remessas=[];const nextId=Math.max(8999,...db.remessas.map(x=>x.id))+1;db.remessas.unshift({id:nextId,data:new Date().toISOString().slice(0,10),banco:'Banco demonstrativo',boletos:boletos.length,valor:boletos.reduce((sum,x)=>sum+Number(x.valor),0),status:'Gerada'});saveData();showToast('Remessa gerada com os boletos pendentes.');render('remessas')}
var originalRenderForRemessas=render;render=function(page=currentPage,options={}){if(page!=='remessas')return originalRenderForRemessas(page,options);currentPage=page;document.getElementById('content').innerHTML=remessasPage();document.querySelectorAll('.nav-item,.nav-subitem').forEach(x=>x.classList.toggle('active',x.dataset.page===page));bindPage();document.querySelector('[data-create-remessa]')?.addEventListener('click',createRemessa);document.getElementById('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})};
function normalizeDashboardChartLabels(){const labels=document.querySelectorAll('.chart-labels span');const expected=['Orçamentos','Orçamento aprovado','Separação','Nota emitida','Contas a receber'];if(labels.length>=5)labels.forEach((label,index)=>{if(label.textContent!==expected[index])label.textContent=expected[index]})}
normalizeDashboardChartLabels();new MutationObserver(normalizeDashboardChartLabels).observe(document.getElementById('content'),{childList:true,subtree:true});
function renderClientPurchaseHistory(name){const target=document.getElementById('clientPurchaseHistory');if(!target)return;const orders=db.pedidos.filter(order=>order.comprador===name).sort((a,b)=>String(b.emissao).localeCompare(String(a.emissao)));const items=orders.flatMap(order=>(order.itens||[]).map(item=>({date:order.emissao,order:order.id,quantity:item.quantidade,product:db.produtos.find(product=>Number(product.id)===Number(item.produtoId))}))).filter(item=>item.product);target.innerHTML=items.length?`<div class="client-purchase-history-title"><strong>Últimos produtos comprados</strong><small>Ordenados pela compra mais recente</small></div><div class="client-purchase-history-list">${items.slice(0,12).map(item=>`<div><span><strong>${escapeHtml(item.product.nome)}</strong><small>Pedido #${item.order} · ${datePt(item.date)}</small></span><b>${item.quantity} un.</b></div>`).join('')}</div>`:name?'<div class="filter-empty">Nenhuma compra detalhada encontrada para este cliente.</div>':''}
document.addEventListener('change',event=>{if(event.target.matches('#recordForm select[name="comprador"]'))renderClientPurchaseHistory(event.target.value)});
function ensureClientPurchaseHistoryPanel(){const select=document.querySelector('#recordForm select[name="comprador"]');if(!select||document.getElementById('clientPurchaseHistory'))return;if(editContext?.type!=='orcamentos')return;select.closest('label')?.insertAdjacentHTML('afterend','<div id="clientPurchaseHistory" class="client-purchase-history"></div>');renderClientPurchaseHistory(select.value)}
new MutationObserver(ensureClientPurchaseHistoryPanel).observe(document.getElementById('formFields'),{childList:true,subtree:true});
function showClientRecentPurchases(clientId){const client=db.compradores.find(item=>Number(item.id)===Number(clientId));if(!client)return;const orders=db.pedidos.filter(order=>order.comprador===client.nome).sort((a,b)=>String(b.emissao).localeCompare(String(a.emissao)));const rows=orders.flatMap(order=>(order.itens||[]).map(item=>{const product=db.produtos.find(product=>Number(product.id)===Number(item.produtoId));return {date:order.emissao,name:product?.nome||'Produto não detalhado',quantity:item.quantidade,order:order.id}}));document.getElementById('modalTitle').textContent='Últimas compras';document.getElementById('modalDescription').textContent=`${client.nome} · histórico recente`;document.getElementById('formFields').innerHTML=rows.length?`<div class="client-purchases-list">${rows.slice(0,20).map(row=>`<div><span><strong>${escapeHtml(row.name)}</strong><small>Pedido #${row.order} · ${datePt(row.date)}</small></span><b>${row.quantity} un.</b></div>`).join('')}</div>`:orders.length?`<div class="filter-empty">Há ${orders.length} pedido(s) para este cliente, mas os itens ainda não foram detalhados.</div>`:'<div class="filter-empty">Nenhuma compra registrada para este cliente.</div>';document.getElementById('modalSubmit').hidden=true;document.getElementById('modalCancel').textContent='Fechar';document.getElementById('modalCancel').onclick=()=>{document.getElementById('modalSubmit').hidden=false;document.getElementById('modalCancel').textContent='Cancelar';closeModal()};document.getElementById('modalError').textContent='';openModal()}
function rebuyClientItem(clientId,productId,quantity){const client=db.compradores.find(item=>Number(item.id)===Number(clientId));const product=db.produtos.find(item=>Number(item.id)===Number(productId));if(!client||!product)return;const qty=Math.max(1,Number(quantity)||1);const id=Math.max(1000,...db.pedidos.map(order=>Number(order.id)||0))+1;checkpoint();db.pedidos.unshift({id,comprador:client.nome,emissao:new Date().toISOString().slice(0,10),valor:Number(product.valorVenda||0)*qty,status:'Rascunho',itens:[{produtoId:product.id,quantidade:qty}],editadoPor:'Lucas Almeida',editadoEm:new Date().toISOString().slice(0,10)});saveData();document.getElementById('modalSubmit').hidden=false;document.getElementById('modalCancel').textContent='Cancelar';closeModal();showToast('Pedido de recompra criado como rascunho.');render('pedidos')}
function showClientRecentPurchases(clientId){const client=db.compradores.find(item=>Number(item.id)===Number(clientId));if(!client)return;const orders=db.pedidos.filter(order=>order.comprador===client.nome).sort((a,b)=>String(b.emissao).localeCompare(String(a.emissao)));const rows=orders.flatMap(order=>(order.itens||[]).map(item=>{const product=db.produtos.find(product=>Number(product.id)===Number(item.produtoId));return {date:order.emissao,name:product?.nome||'Produto não detalhado',productId:item.produtoId,quantity:item.quantidade,order:order.id}}));document.getElementById('modalTitle').textContent='Últimas compras';document.getElementById('modalDescription').textContent=`${client.nome} · histórico recente`;document.getElementById('formFields').innerHTML=rows.length?`<div class="client-purchases-list">${rows.slice(0,20).map(row=>`<div><span><strong>${escapeHtml(row.name)}</strong><small>Pedido #${row.order} · ${datePt(row.date)}</small></span><b>${row.quantity} un.</b><button type="button" class="action-button" data-client-rebuy="${client.id}:${row.productId}:${row.quantity}">Recomprar</button></div>`).join('')}</div>`:orders.length?`<div class="filter-empty">Há ${orders.length} pedido(s) para este cliente, mas os itens ainda não foram detalhados.</div>`:'<div class="filter-empty">Nenhuma compra registrada para este cliente.</div>';document.getElementById('modalSubmit').hidden=true;document.getElementById('modalCancel').textContent='Fechar';document.getElementById('modalCancel').onclick=()=>{document.getElementById('modalSubmit').hidden=false;document.getElementById('modalCancel').textContent='Cancelar';closeModal()};document.getElementById('modalError').textContent='';openModal()}
document.addEventListener('click',event=>{const button=event.target.closest('[data-client-rebuy]');if(!button)return;const [clientId,productId,quantity]=button.dataset.clientRebuy.split(':');rebuyClientItem(Number(clientId),Number(productId),Number(quantity))});
function rebuyClientOrder(clientId,orderId){const client=db.compradores.find(item=>Number(item.id)===Number(clientId));const original=db.pedidos.find(order=>Number(order.id)===Number(orderId));if(!client||!original)return;const items=(original.itens||[]).map(item=>({produtoId:Number(item.produtoId),quantidade:Number(item.quantidade)||1}));if(!items.length){showToast('Este pedido não possui itens detalhados para recomprar.');return}const id=Math.max(1000,...db.pedidos.map(order=>Number(order.id)||0))+1;const value=items.reduce((sum,item)=>sum+item.quantidade*Number(db.produtos.find(product=>Number(product.id)===item.produtoId)?.valorVenda||0),0);checkpoint();db.pedidos.unshift({id,comprador:client.nome,emissao:new Date().toISOString().slice(0,10),valor:value,status:'Rascunho',itens:items,editadoPor:'Lucas Almeida',editadoEm:new Date().toISOString().slice(0,10)});saveData();document.getElementById('modalSubmit').hidden=false;document.getElementById('modalCancel').textContent='Cancelar';closeModal();showToast('Recompra criada com base no último pedido.');render('pedidos')}
function showClientRecentPurchases(clientId){const client=db.compradores.find(item=>Number(item.id)===Number(clientId));if(!client)return;const orders=db.pedidos.filter(order=>order.comprador===client.nome).sort((a,b)=>String(b.emissao).localeCompare(String(a.emissao)));document.getElementById('modalTitle').textContent='Últimas compras';document.getElementById('modalDescription').textContent=`${client.nome} · cada recompra usa o pedido inteiro como base`;document.getElementById('formFields').innerHTML=orders.length?`<div class="client-purchases-list">${orders.slice(0,10).map(order=>{const items=(order.itens||[]).map(item=>{const product=db.produtos.find(product=>Number(product.id)===Number(item.produtoId));return `${escapeHtml(product?.nome||'Produto não detalhado')} (${item.quantidade} un.)`}).join(', ');return `<div><span><strong>Pedido #${order.id}</strong><small>${datePt(order.emissao)} · ${items||'Itens não detalhados'}</small></span><button type="button" class="action-button" data-client-rebuy-order="${client.id}:${order.id}" ${order.itens?.length?'':'disabled'}>Recomprar</button></div>`}).join('')}</div>`:'<div class="filter-empty">Nenhuma compra registrada para este cliente.</div>';document.getElementById('modalSubmit').hidden=true;document.getElementById('modalCancel').textContent='Fechar';document.getElementById('modalCancel').onclick=()=>{document.getElementById('modalSubmit').hidden=false;document.getElementById('modalCancel').textContent='Cancelar';closeModal()};document.getElementById('modalError').textContent='';openModal()}
document.addEventListener('click',event=>{const button=event.target.closest('[data-client-rebuy-order]');if(!button)return;const [clientId,orderId]=button.dataset.clientRebuyOrder.split(':');rebuyClientOrder(Number(clientId),Number(orderId))});
function showClientRecentPurchases(clientId){const client=db.compradores.find(item=>Number(item.id)===Number(clientId));if(!client)return;const orders=db.pedidos.filter(order=>order.comprador===client.nome).sort((a,b)=>String(b.emissao).localeCompare(String(a.emissao)));const renderRows=query=>{const normalized=String(query||'').toLocaleLowerCase('pt-BR').trim();const rows=orders.flatMap(order=>(order.itens||[]).map(item=>{const product=db.produtos.find(product=>Number(product.id)===Number(item.produtoId));return {order,date:order.emissao,item,product}})).filter(row=>row.product&&(!normalized||`${row.product.nome} ${row.product.sku||''}`.toLocaleLowerCase('pt-BR').includes(normalized)));return rows.length?`<div class="client-purchases-list">${rows.slice(0,30).map(row=>`<div><span><strong>${escapeHtml(row.product.nome)}</strong><small>SKU: ${escapeHtml(row.product.sku||'Sem SKU')} · Pedido #${row.order.id} · ${datePt(row.date)}</small></span><b>${row.item.quantidade} un.</b><button type="button" class="action-button" data-client-rebuy-order="${client.id}:${row.order.id}">Recomprar pedido</button></div>`).join('')}</div>`:`<div class="filter-empty">Nenhum produto encontrado no histórico deste cliente.</div>`};document.getElementById('modalTitle').textContent='Últimas compras';document.getElementById('modalDescription').textContent=`${client.nome} · pesquise por produto ou SKU`;document.getElementById('formFields').innerHTML=`<label class="client-purchase-search-label">Pesquisar produto<input id="clientPurchaseSearch" placeholder="Nome ou SKU do produto..."></label><div id="clientPurchaseResults">${renderRows('')}</div>`;document.getElementById('clientPurchaseSearch').addEventListener('input',event=>{document.getElementById('clientPurchaseResults').innerHTML=renderRows(event.target.value)});document.getElementById('modalSubmit').hidden=true;document.getElementById('modalCancel').textContent='Fechar';document.getElementById('modalCancel').onclick=()=>{document.getElementById('modalSubmit').hidden=false;document.getElementById('modalCancel').textContent='Cancelar';closeModal()};document.getElementById('modalError').textContent='';openModal()}
function openContextActionMenu(target,x,y){closeContextActionMenu();const source=target.dataset.rowEdit||target.dataset.flowEdit;if(!source)return;const [type,id]=source.split(':');contextActionMenu=document.createElement('div');contextActionMenu.className='context-action-menu';contextActionMenu.innerHTML=`<button type="button" data-context-open>Abrir</button>${type==='compradores'?'<button type="button" data-context-purchases>Últimas compras</button>':''}<button type="button" data-context-duplicate>Duplicar</button><button type="button" data-context-delete>Apagar</button>`;contextActionMenu.style.left=`${Math.min(x,window.innerWidth-170)}px`;contextActionMenu.style.top=`${Math.min(y,window.innerHeight-150)}px`;document.body.appendChild(contextActionMenu);contextActionMenu.querySelector('[data-context-open]').onclick=()=>{closeContextActionMenu();openForm(type,Number(id))};contextActionMenu.querySelector('[data-context-purchases]')?.addEventListener('click',()=>{closeContextActionMenu();showClientRecentPurchases(Number(id))});contextActionMenu.querySelector('[data-context-duplicate]').onclick=()=>{closeContextActionMenu();duplicateRecord(type,Number(id))};contextActionMenu.querySelector('[data-context-delete]').onclick=()=>{closeContextActionMenu();removeRecord(type,Number(id))}}
function purchaseSuggestionHtml(){const purchases=db.compras||[],suppliers=db.fornecedores||[];const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-purchaseSuggestionDays);const scoped=purchases.filter(x=>new Date(`${x.data}T12:00:00`)>=cutoff&&(purchaseSuggestionSupplier==='all'||String(x.fornecedorId)===purchaseSuggestionSupplier));const months=Math.max(purchaseSuggestionDays/30,1);const rows=db.produtos.map(product=>{const purchased=scoped.reduce((sum,order)=>sum+order.itens.filter(i=>i.produtoId===product.id).reduce((s,i)=>s+Number(i.quantidade),0),0);const monthly=purchased/months;const suggested=Math.max(0,Math.ceil(monthly-monthly*0+0)-Number(product.estoque));return {...product,purchased,monthly,suggested}}).filter(x=>x.suggested>0).sort((a,b)=>b.suggested-a.suggested);return `<section class="card purchase-suggestion-card"><div class="panel-head"><div><h2>Sugestão de compra</h2><small>Estimativa baseada no histórico do período e no fornecedor selecionado.</small></div></div><div class="purchase-suggestion-filters"><label>Período<select data-purchase-period><option value="30" ${purchaseSuggestionDays===30?'selected':''}>Últimos 30 dias</option><option value="90" ${purchaseSuggestionDays===90?'selected':''}>Últimos 90 dias</option><option value="180" ${purchaseSuggestionDays===180?'selected':''}>Últimos 6 meses</option><option value="365" ${purchaseSuggestionDays===365?'selected':''}>Último ano</option></select></label><label>Fornecedor<select data-purchase-supplier><option value="all">Todos os fornecedores</option>${suppliers.map(x=>`<option value="${x.id}" ${String(x.id)===purchaseSuggestionSupplier?'selected':''}>${escapeHtml(x.nome)}</option>`).join('')}</select></label></div>${rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Produto</th><th>Estoque atual</th><th>Consumo no período</th><th>Média mensal</th><th>Sugerido comprar</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${escapeHtml(x.nome)}</strong></td><td>${x.estoque} un.</td><td>${x.purchased} un.</td><td>${x.monthly.toLocaleString('pt-BR',{maximumFractionDigits:1})} un.</td><td><span class="badge amber">${x.suggested} un.</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="filter-empty">Nenhum produto precisa de reposição neste filtro.</div>'}</section>`}
var originalListingForPurchaseSuggestion=listing;listing=function(type,subset){const html=originalListingForPurchaseSuggestion(type,subset);if(type!=='produtos'||subset)return html;return html.replace('<div class="card table-card">',purchaseSuggestionHtml()+'<div class="card table-card">')};document.addEventListener('change',e=>{if(e.target.matches('[data-purchase-period]')){purchaseSuggestionDays=Number(e.target.value);render('produtos')}if(e.target.matches('[data-purchase-supplier]')){purchaseSuggestionSupplier=e.target.value;render('produtos')}});
var baseRenderWithPurchaseSuggestion=render;render=function(page=currentPage,options={}){baseRenderWithPurchaseSuggestion(page,options);if(page==='produtos'&&!document.querySelector('.purchase-suggestion-card')){const tableCard=document.querySelector('.content .table-card');if(tableCard)tableCard.insertAdjacentHTML('beforebegin',purchaseSuggestionHtml())}};
